import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)

    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []
    processes = []

    for file_path in files:
        try:
            p = subprocess.Popen(['gzip', '-f', file_path])
            processes.append((file_path, p))
        except Exception:
            failed_files.append(os.path.basename(file_path))

    for file_path, p in processes:
        p.wait()
        gz_file_path = file_path + '.gz'
        if p.returncode == 0 and os.path.exists(gz_file_path):
            try:
                shutil.move(gz_file_path, os.path.join(dst_folder, os.path.basename(gz_file_path)))
            except Exception:
                failed_files.append(os.path.basename(file_path))
        else:
            failed_files.append(os.path.basename(file_path))

    success = len(failed_files) == 0
    message = "All files compressed and moved successfully." if success else "Some files failed to compress or move."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

